from datetime import datetime
import re


def is_valid_expiry_date(expiry_date: str, allow_past: bool = False) -> bool:
    """Check if expiry date is in MM/YY format and not expired.

    Args:
        expiry_date: String in MM/YY format
        allow_past: If True, don't check expiration date

    Returns:
        True if valid format and not expired (unless allow_past=True)
    """
    if not re.match(r'^\d{2}/\d{2}$', expiry_date):
        return False

    try:
        month, year = map(int, expiry_date.split('/'))
        if month < 1 or month > 12:
            return False

        # Convert 2-digit year to 4-digit (assuming 2000s)
        year = 2000 + year

        if not allow_past:
            # Check if expired (end of expiry month)
            expiry_end = datetime(year, month, 28)  # Safe date within month
            if expiry_end < datetime.now():
                return False

    except ValueError:
        return False

    return True


def is_valid_zip_code(zip_code: str, country: str) -> bool:
    """Validate zip code based on country.

    Args:
        zip_code: The zip/postal code to validate
        country: ISO country code (US, CA, etc.)

    Returns:
        True if valid format for the country
    """
    if country == "US":
        return bool(re.match(r'^\d{5}$', zip_code))
    elif country == "CA":
        # Canadian postal code: A1A 1A1 format (alphanumeric, alternating)
        return bool(re.match(r'^[A-Za-z]\d[A-Za-z] ?\d[A-Za-z]\d$', zip_code))
    else:
        # For other countries, accept 3-10 alphanumeric characters
        return bool(re.match(r'^[A-Za-z0-9]{3,10}$', zip_code))


def contains_pan(data: dict) -> bool:
    """Recursively check if dictionary contains any field that looks like a PAN.

    Args:
        data: Dictionary to search

    Returns:
        True if any field contains a potential PAN
    """
    # Regular expression for credit card numbers (simplified)
    pan_pattern = re.compile(r'\b(?:\d[ -]*?){13,16}\b')

    def search_dict(d):
        if not isinstance(d, dict):
            return False

        for key, value in d.items():
            # Check key name
            if 'pan' in key.lower() or 'card' in key.lower() or 'account' in key.lower():
                # Check if value looks like a card number
                if isinstance(value, str) and pan_pattern.search(value):
                    return True

            # Check string values
            if isinstance(value, str) and pan_pattern.search(value):
                return True

            # Recursively check nested structures
            if isinstance(value, dict) and search_dict(value):
                return True

            if isinstance(value, list):
                for item in value:
                    if isinstance(item, dict) and search_dict(item):
                        return True

        return False

    return search_dict(data)

